pub fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    assert_eq!(dst.len(), src.len(), "dst and src must have the same length");
    assert_eq!(dst.len(), mask.len(), "mask must have the same length as dst/src");

    let mut result = Vec::with_capacity(dst.len());
    for i in 0..dst.len() {
        result.push(if mask[i] { src[i] } else { dst[i] });
    }
    result
}